#include "research_runs_page.hpp"
#include "research_runs_model.hpp"
#include "legacy_data.hpp"
#include <QComboBox>
#include <QLineEdit>
#include <QListWidget>
#include <QPlainTextEdit>
#include <QLabel>
#include <QPushButton>
#include <QBoxLayout>
#include <QSplitter>
#include <QFileDialog>
#include <QSaveFile>
#include <QFile>
ResearchRunsPage::ResearchRunsPage(std::shared_ptr<BusinessStore> s,QWidget* p):QWidget(p),store(std::move(s)){
 setObjectName("researchRunsPage");auto layout=new QVBoxLayout(this);auto actions=new QHBoxLayout;layout->addLayout(actions);
 auto button=[&](QString text,QString name,auto fn){auto b=new QPushButton(text,this);b->setObjectName(name);actions->addWidget(b);connect(b,&QPushButton::clicked,this,fn);return b;};
 button("导入旧研究 JSON / SQLite","researchRunsImport",[this]{importFile();});button("导出研究备份","researchRunsExport",[this]{exportFile();});button("重读","researchRunsReload",[this]{reload();});
 auto filters=new QHBoxLayout;layout->addLayout(filters);types=new QComboBox;statuses=new QComboBox;models=new QComboBox;search=new QLineEdit;search->setPlaceholderText("标题 / 问题 / 原ID");types->setObjectName("researchRunsType");statuses->setObjectName("researchRunsStatus");models->setObjectName("researchRunsModel");search->setObjectName("researchRunsSearch");for(auto c:{types,statuses,models})filters->addWidget(c);filters->addWidget(search,1);
 for(auto c:{types,statuses,models})connect(c,&QComboBox::currentIndexChanged,this,[this]{if(!filling){page=0;render();}});connect(search,&QLineEdit::textChanged,this,[this]{if(!filling){page=0;render();}});
 previewReader=new QPlainTextEdit;previewReader->setReadOnly(true);previewReader->setObjectName("researchRunsPreview");previewReader->setMaximumHeight(150);previewReader->hide();layout->addWidget(previewReader);auto review=new QHBoxLayout;layout->addLayout(review);confirm=new QPushButton("确认合并（保留冲突）");cancel=new QPushButton("取消预览");confirm->setObjectName("researchRunsConfirm");cancel->setObjectName("researchRunsCancel");review->addWidget(confirm);review->addWidget(cancel);confirm->hide();cancel->hide();connect(confirm,&QPushButton::clicked,this,[this]{confirmImport();});connect(cancel,&QPushButton::clicked,this,[this]{cancelImport();});
 auto split=new QSplitter;layout->addWidget(split,1);list=new QListWidget;reader=new QPlainTextEdit;reader->setReadOnly(true);list->setObjectName("researchRunsList");reader->setObjectName("researchRunsOriginal");split->addWidget(list);split->addWidget(reader);split->setStretchFactor(1,3);connect(list,&QListWidget::currentRowChanged,this,[this](int n){choose(n);});
 auto paging=new QHBoxLayout;layout->addLayout(paging);previous=new QPushButton("上一页");next=new QPushButton("下一页");state=new QLabel;state->setWordWrap(true);previous->setObjectName("researchRunsPrevious");next->setObjectName("researchRunsNext");state->setObjectName("researchRunsState");paging->addWidget(previous);paging->addWidget(state,1);paging->addWidget(next);connect(previous,&QPushButton::clicked,this,[this]{--page;render();});connect(next,&QPushButton::clicked,this,[this]{++page;render();});reload();restore();
}
ResearchRunsPage::~ResearchRunsPage(){persist();}
void ResearchRunsPage::reload(){try{auto t=types->currentData().toString(),s=statuses->currentData().toString(),m=models->currentData().toString();all=store->read("reports");filling=true;for(auto pair:{qMakePair(types,QString("runType")),qMakePair(statuses,QString("status")),qMakePair(models,QString("modelId"))}){pair.first->clear();pair.first->addItem("全部","");QSet<QString> values;for(auto v:all){auto r=v.toObject();if(r["legacySource"]=="ai_research_runs")values.insert(r["researchRun"].toObject()[pair.second].toString());}auto ordered=values.values();ordered.sort();for(auto value:ordered)pair.first->addItem(value,value);}types->setCurrentIndex(qMax(0,types->findData(t)));statuses->setCurrentIndex(qMax(0,statuses->findData(s)));models->setCurrentIndex(qMax(0,models->findData(m)));filling=false;render();}catch(const std::exception& e){filling=false;state->setText(QString::fromUtf8(e.what()));}}
void ResearchRunsPage::render(){filtered=researchRuns::filter(all,types->currentData().toString(),statuses->currentData().toString(),models->currentData().toString(),search->text());page=qBound(0,page,qMax(0,(int(filtered.size())-1)/50));filling=true;list->clear();reader->clear();int chosen=-1;for(int i=page*50;i<qMin(int(filtered.size()),(page+1)*50);++i){auto r=filtered[i].toObject(),run=r["researchRun"].toObject();list->addItem(run["title"].toString()+" · "+run["status"].toString()+"\n"+run["runType"].toString()+" / "+run["modelId"].toString()+" · "+run["createdAt"].toString());if(r["id"]==selected)chosen=i-page*50;}filling=false;if(chosen>=0)list->setCurrentRow(chosen);previous->setEnabled(page>0);next->setEnabled((page+1)*50<filtered.size());state->setText(QString("历史研究 %1 条 · 筛选 %2 条 · 第 %3/%4 页").arg(researchRuns::filter(all,"","","","").size()).arg(filtered.size()).arg(page+1).arg(qMax(1,(int(filtered.size())+49)/50)));}
void ResearchRunsPage::choose(int n){if(filling||n<0||page*50+n>=filtered.size())return;auto r=filtered[page*50+n].toObject();selected=r["id"].toString();reader->setPlainText(researchRuns::read(r));}
void ResearchRunsPage::previewImport(const QByteArray& bytes){cancelImport();try{incoming=researchRuns::decode(bytes);baseline=store->read("reports");auto p=researchRuns::preview(incoming,baseline);previewReader->setPlainText(QString("总计 %1 · 新增 %2 · 同文跳过 %3 · 冲突保留 %4\n%5\n\n").arg(incoming.size()).arg(p["insert"].toArray().size()).arg(p["duplicates"].toInt()).arg(p["conflicts"].toArray().size()).arg(QString::fromUtf8(QJsonDocument(p["conflicts"].toArray()).toJson()))+QString::fromUtf8(QJsonDocument(incoming).toJson()));pending=true;researchRuns::need(persist(),"预览保存失败或超过64MB，请分批导入，未启用确认");previewReader->show();confirm->show();cancel->show();confirm->setEnabled(true);}catch(const std::exception& e){cancelImport();state->setText(QString::fromUtf8(e.what()));}}
void ResearchRunsPage::confirmImport(){if(!pending)return;try{auto p=researchRuns::preview(incoming,baseline);store->mergeResearchReports(p["insert"].toArray(),baseline);auto message=QString("已合并 %1 条；冲突保留 %2 条；未执行旧运行").arg(p["insert"].toArray().size()).arg(p["conflicts"].toArray().size());cancelImport();reload();state->setText(message);}catch(const std::exception& e){state->setText(QString::fromUtf8(e.what()));}}
void ResearchRunsPage::cancelImport(){pending=false;incoming={};baseline={};previewReader->clear();previewReader->hide();confirm->hide();cancel->hide();persist();}
void ResearchRunsPage::importFile(){auto path=QFileDialog::getOpenFileName(this,"选择本地旧研究记录",{},"JSON / SQLite (*.json *.db *.sqlite *.sqlite3);;全部文件 (*)");if(path.isEmpty())return;try{if(path.endsWith(".json",Qt::CaseInsensitive)){QFile f(path);researchRuns::need(f.open(QIODevice::ReadOnly)&&f.size()<=32*1024*1024,"文件不可读或超过32MB");previewImport(f.readAll());}else previewImport(QJsonDocument(legacydata::readResearchRuns(path)).toJson());}catch(const std::exception& e){state->setText(QString::fromUtf8(e.what()));}}
void ResearchRunsPage::exportFile(){auto path=QFileDialog::getSaveFileName(this,"导出研究备份",{},"JSON (*.json)");if(path.isEmpty())return;QSaveFile f(path);auto bytes=QJsonDocument(researchRuns::backup(store->read("reports"))).toJson();if(!f.open(QIODevice::WriteOnly)||f.write(bytes)!=bytes.size()||!f.commit())state->setText("导出失败，未替换原文件");else state->setText("研究备份已导出，原文与状态保留");}
QJsonObject ResearchRunsPage::saveState()const{return {{"schema","research-runs-state/v1"},{"type",types->currentData().toString()},{"status",statuses->currentData().toString()},{"model",models->currentData().toString()},{"search",search->text()},{"page",page},{"selected",selected},{"pending",pending},{"incoming",incoming},{"baseline",baseline}};}
void ResearchRunsPage::restoreState(const QJsonObject& s){if(s["schema"]!="research-runs-state/v1")return;filling=true;types->setCurrentIndex(qMax(0,types->findData(s["type"])));statuses->setCurrentIndex(qMax(0,statuses->findData(s["status"])));models->setCurrentIndex(qMax(0,models->findData(s["model"])));search->setText(s["search"].toString());page=s["page"].toInt();selected=s["selected"].toString();filling=false;render();if(s["pending"].toBool()){try{incoming=researchRuns::decode(QJsonDocument(researchRuns::backup(s["incoming"].toArray())).toJson());baseline=s["baseline"].toArray();auto p=researchRuns::preview(incoming,baseline);previewReader->setPlainText(QString("恢复待确认预览：新增 %1 · 同文跳过 %2 · 冲突保留 %3\n\n").arg(p["insert"].toArray().size()).arg(p["duplicates"].toInt()).arg(p["conflicts"].toArray().size())+QString::fromUtf8(QJsonDocument(incoming).toJson()));pending=true;previewReader->show();confirm->show();cancel->show();confirm->setEnabled(true);}catch(const std::exception& e){state->setText(QString::fromUtf8(e.what()));}}}
bool ResearchRunsPage::persist(){auto bytes=QJsonDocument(saveState()).toJson();if(bytes.size()>64*1024*1024)return false;QSaveFile f(store->filePath()+".research-runs-view.json");return f.open(QIODevice::WriteOnly)&&f.write(bytes)==bytes.size()&&f.commit();}
void ResearchRunsPage::restore(){QFile f(store->filePath()+".research-runs-view.json");if(f.open(QIODevice::ReadOnly)&&f.size()<=64*1024*1024)restoreState(QJsonDocument::fromJson(f.readAll()).object());}
